<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Send your question to our support team and we will get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required>
        <p class="error-text" id="full-name-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
        <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required>
        <p class="error-text" id="email-address-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="(555) 123-4567">
        <p class="helper-text" id="phone-number-helper">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
        <p class="error-text" id="phone-number-error" aria-live="polite"></p>
      </div>

      <button type="submit">Submit request</button>
      <p class="status" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Please enter your full name.";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Please enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          return emailPattern.test(value) ? "" : "Please enter a valid email address.";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          const phonePattern = /^[+]?[\d()\s-]{7,20}$/;
          return phonePattern.test(value) ? "" : "Please use a valid phone format.";
        }
